head.script:
scwin.exceldown = function() { //useStyle 부분 추가
    var options = {};
    options.fileName = "excel.xlsx";
    options.type = "1";
    options.useStyle = "true";
    options.spanAll = "true";
    options.rowHeight = "50";
    gridView1.advancedExcelDownload(options);
};
scwin.trigger2_onclick = function(e) {
    var excelOpt = {};
    excelOpt.startRowIndex = 1;
    excelOpt.startColumnIndex = 0;
    excelOpt.endColumnIndex = 1;
    excelOpt.separator = "|||";
    gridView1.advancedExcelUpload(excelOpt);
};
scwin.onpageload = function() {
    window.json1 = [{
            "col1": '"Test1"',
            "col2": "A"
        },
        {
            "col1": '"Test2"',
            "col2": "B"
        },
        {
            "col1": '"Test3"',
            "col2": "C"
        },
        {
            "col1": '"Test4"',
            "col2": "D"
        },
        {
            "col1": '"Test5"',
            "col2": "E"
        },
        {
            "col1": '"Test6"',
            "col2": "F"
        }
    ];
    dataList1.setJSON(json1);
    /*		scwin.trigger1_onclick = function(e) {
    			window.excelOpt = {};  //excel download 옵션 
    			excelOpt.fileName = "excelData%.xls";    //또는 xlsx 확장자 사용 
    			excelOpt.separator = "|||";

    			gridView1.advancedExcelDownload( excelOpt );

    		}; */ //기존에 있는 엑셀 다운로드 기능 추석처리
    scwin.trigger1_onclick = function(e) { //새로운 엑셀 다운로드 기능
        scwin.exceldown();
    };
    gridView1.setCellColor(0, 1, "red"); //setCellColor 부분 추가
}
